{"path":"apps/react-vite/src/features/comments/components/update-comment.tsx","content":"import { Pencil } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { FormDrawer, Form, Textarea } from '@/components/ui/form';
import { useNotifications } from '@/components/ui/notifications';

import {
  useUpdateComment,
  updateCommentInputSchema,
  UpdateCommentInput,
} from '../api/update-comment';

type UpdateCommentProps = {
  id: string;
  discussionId: string;
  currentBody: string;
};

export const UpdateComment = ({ id, discussionId, currentBody }: UpdateCommentProps) => {
  const { addNotification } = useNotifications();
  const updateCommentMutation = useUpdateComment({
    discussionId,
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Comment Updated',
        });
      },
    },
  });

  return (
    <FormDrawer
      isDone={updateCommentMutation.isSuccess}
      triggerButton={
        <Button variant="ghost" size="sm" icon={<Pencil className="size-4" />}>
          Edit
        </Button>
      }
      title="Edit Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="update-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Save
        </Button>
      }
    >
      <Form
        id="update-comment"
        onSubmit={(values: UpdateCommentInput) => {
          updateCommentMutation.mutate({
            commentId: id,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: currentBody,
          },
        }}
      >
        {({ register, formState }) => (
          <Textarea
            label="Body"
            error={formState.errors['body']}
            registration={register('body')}
          />
        )}
      </Form>
    </FormDrawer>
  );
};
"}

